import{_ as a,o as t,c as r,j as s}from"./chunks/framework.DsyGq6Zh.js";const h=JSON.parse('{"title":"From Messy Multimodal Sources to Qualified Knowledge","description":"Claims, provenance, contradictions, graph/vector retrieval, and a UAP corpus pilot for governed knowledge construction.","frontmatter":{"title":"From Messy Multimodal Sources to Qualified Knowledge","description":"Claims, provenance, contradictions, graph/vector retrieval, and a UAP corpus pilot for governed knowledge construction."},"headers":[],"relativePath":"research/systems/provenance-knowledge-graphs.md","filePath":"research/systems/provenance-knowledge-graphs.md"}'),o={name:"research/systems/provenance-knowledge-graphs.md"};function i(n,e,c,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="from-messy-multimodal-sources-to-qualified-knowledge" tabindex="-1">From Messy Multimodal Sources to Qualified Knowledge <a class="header-anchor" href="#from-messy-multimodal-sources-to-qualified-knowledge" aria-label="Permalink to &quot;From Messy Multimodal Sources to Qualified Knowledge&quot;">​</a></h1><p><em>Research proposal and corpus case study · November 2026</em></p><p>A knowledge graph should help explain what happened across a large collection, without pretending that every statement in the collection is true.</p><p>Consider millions of emails or decades of UFO/UAP material. Some documents copy the same statement. Others contradict it. Dates, names, agencies, witnesses, publishers, and interpretations change. A retrieval system can summarize these materials fluently while inadvertently losing the distinction between <em>someone reported X</em> and <em>X occurred</em>.</p><p>I want to build systems where those distinctions survive extraction, compression, and reuse.</p><h2 id="separate-four-things" tabindex="-1">Separate four things <a class="header-anchor" href="#separate-four-things" aria-label="Permalink to &quot;Separate four things&quot;">​</a></h2><ul><li><strong>Source:</strong> original file, identity, representation, access rights, content hash, and passage or time interval.</li><li><strong>Observation:</strong> what a parser, sensor, or model extracted from that source, along with tool version and confidence or limitations.</li><li><strong>Candidate claim:</strong> a proposition connected to speakers, events, and supporting or conflicting evidence.</li><li><strong>Qualified knowledge:</strong> a claim approved for a particular use under a recorded rule or authorized decision—not an unconditional declaration of truth.</li></ul><p>A human&#39;s review should record <em>what was approved and why</em>, including scope. Approval to index a claim as reported testimony is different from approval to present the claim as established fact.</p><h2 id="why-a-hybrid-graph-and-vector-system" tabindex="-1">Why a hybrid graph and vector system <a class="header-anchor" href="#why-a-hybrid-graph-and-vector-system" aria-label="Permalink to &quot;Why a hybrid graph and vector system&quot;">​</a></h2><p>Vectors help find semantically related passages; full-text and exact indexes find specific names and identifiers. The graph organizes claims, identities, evidence lineages, time, agreement, and contradiction.</p><p>A small retrieved subgraph could answer <em>which actors, claims, and sources matter to this question?</em> The system would then retrieve exact passages before making consequential conclusions.</p><p>This is <strong>structured compression with recoverable evidence</strong>, not lossless compression. Every summary is an interpretation that can omit something important. Evaluation must test whether crucial qualifiers and competing accounts remain available.</p><h2 id="uap-corpus-as-a-difficult-case" tabindex="-1">UAP corpus as a difficult case <a class="header-anchor" href="#uap-corpus-as-a-difficult-case" aria-label="Permalink to &quot;UAP corpus as a difficult case&quot;">​</a></h2><p>My private UAP Corpus (private research catalog) contains a curated metadata-only catalog of <strong>38 source records/leads as of November 12, 2026</strong>, including government archives, hearings, scientific papers, books, historical investigations, and firsthand or secondhand accounts.</p><p>The repository is explicit: no original corpus files have yet been acquired; its claim network is still a plan. Its unpublished network-design notes distinguish firsthand observation, reporting, reprinting, correction, and contradiction.</p><p>A rigorous pilot could start with a small rights-cleared selection, perhaps a government report and relevant congressional testimony. We would preserve source and publication dates separately from event dates, distinguish official positions from independent evidence, and represent uncertainty without forcing a binary conclusion.</p><p>The success criterion would <strong>not</strong> be proving extraterrestrial claims. It would be accurate attribution, shared-source detection, evidence retrieval, contradiction preservation, and transparent qualification.</p><h2 id="sensors-and-the-pit-stop" tabindex="-1">Sensors and the Pit Stop <a class="header-anchor" href="#sensors-and-the-pit-stop" aria-label="Permalink to &quot;Sensors and the Pit Stop&quot;">​</a></h2><p>A citation sensor might detect a missing passage; an identity sensor could find ambiguous names; a source-lineage sensor could find that six articles repeat the same interview. Their outputs would be analyzed independently of permission policies.</p><p>The Race Track can automatically register traceable, low-consequence observations. Potentially damaging allegations, ambiguous identity merges, restricted source rights, and changes to canonical conclusions may require more evidence or an authorized Pit Stop.</p><p>Automatic processing must still undergo sampled independent audit. A sensor that systematically misses errors cannot be made safe simply by routing only its own flagged cases for review.</p><h2 id="literature-and-open-questions" tabindex="-1">Literature and open questions <a class="header-anchor" href="#literature-and-open-questions" aria-label="Permalink to &quot;Literature and open questions&quot;">​</a></h2><p><a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">W3C PROV-O (2013)</a> defines reusable provenance relationships. <a href="https://www.microsoft.com/en-us/research/publication/from-local-to-global-a-graph-rag-approach-to-query-focused-summarization/" target="_blank" rel="noreferrer">GraphRAG (Edge et al., 2024)</a> demonstrates hierarchical graph summaries. <a href="https://aclanthology.org/2026.akbc-1.16/" target="_blank" rel="noreferrer">GRACE (Yi, Minot, and Lee, 2026)</a> explicitly uses a graph of grounded claims and a return-on-attention criterion to select expert review.</p><p>The open research question is whether <strong>heterogeneous, commissioned sensors and consequence-sensitive decision policies</strong> can improve graph integrity and evidence efficiency over these established systems under realistic review constraints.</p><p><a href="./">Research series</a> · <a href="./dissertation-proposal">Dissertation proposal</a></p>',25)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
